STAGES = [("y12", "Year 12", "Year 12 (the AS content)", Y12), ("y13", "Year 13", "Year 13 (the full A level)", Y13)]
ALEVEL = {"y12": "A level Mathematics (Year 12, the AS content)", "y13": "A level Mathematics (Year 13)"}


def lesson(key, course, n, row):
    slug, title, strand, intention, criteria, start, teach, check, home, vocab, understand, look = row
    sheet = f"Exam practice (A level {course}) {n}: {title}"
    return {"id": f"lesson-alevel-maths-{key}-{slug}", "level": "Senior", "subject": "Maths", "strand": strand, "codes": [],
            "title": f"A level maths climb ({course}) {n}: {title}", "intention": intention, "criteria": criteria,
            "steps": {"start": start, "teach": teach,
                      "practise": f"The \"{sheet}\" sheet, marked one bullet a mark (method marks follow through), then the online practice.",
                      "check": check},
            "use": [f"{key}-{slug}"], "home": home, "vocab": vocab, "understand": understand, "lookFor": look,
            "england": True, "alevel": ALEVEL[key]}


lessons = []
for key, course, name, topics in STAGES:
    lessons.append({"id": f"lesson-alevel-maths-{key}-start-here", "level": "Senior", "subject": "Maths", "strand": "Number", "codes": [],
        "title": f"A level maths climb ({course}) start here: check and plan",
        "intention": f"We are finding out which of the {name} topics are already secure and which to learn first, and making a plan.",
        "criteria": [f"I can try one exam question on each of the 14 {course} topics.", "I know which topics I will work on first, and why.", "I know how each topic works: lesson, online practice, exam-style sheet, then mini papers."],
        "steps": {"start": {"y12": "Talk about the goal: A level Mathematics starts with Year 12's pure, statistics and mechanics. Strong GCSE algebra (grade 7 or above) makes it much easier.",
                            "y13": "Talk about the goal: the full A level. Year 13 builds on Year 12, and all three exams cover both years."}[key],
                  "teach": f"Explain the stage: 14 topics in order, each with a lesson, online practice and an exam-style sheet; mini papers every few sessions. Do the {course} check (online or on paper), with a calculator but no help: it is a map, not a test.",
                  "practise": f"The \"A level maths climb: {course} check\" sheet, or the online {course} check.",
                  "check": f"Mark the check together and fill in the \"A level maths climb: {course} tracker\" sheet: the topics that lost marks go first, in climb order."},
        "use": [f"{key}-check"], "home": "Look at the tracker together and agree a weekly time for online practice.",
        "vocab": "specification, paper, mark scheme, method mark, accuracy mark, secure",
        "understand": "Why work through the topics in the climb's order rather than starting with the hardest?",
        "lookFor": "Says the early topics (algebra, trig, calculus) are used inside the later ones, so they make the later topics easier.",
        "england": True, "alevel": ALEVEL[key]})
    for i, row in enumerate(topics, 1):
        lessons.append(lesson(key, course, i, row))
    lessons.append({"id": f"lesson-alevel-maths-{key}-mini-papers", "level": "Senior", "subject": "Maths", "strand": "Number", "codes": [],
        "title": f"A level maths climb: mini papers ({course})",
        "intention": "We are practising exam questions from all the topics together, under exam conditions, and using the results to plan what to revise.",
        "criteria": ["I can answer mixed exam questions without being told the topic.", "I show my working on every question.", "I can use my marks to choose which topics to go back to."],
        "steps": {"start": "Recap the habits: read twice, underline the command word, one step a line, 3 significant figures at the end, conclusions in context.",
                  "teach": "Set up exam conditions: 20 to 25 minutes, quiet, calculator allowed. Remind them to do the questions they can first.",
                  "practise": f"One of the \"Mini paper: pure maths (A level {course})\", \"Mini paper: statistics and mechanics (A level {course})\" or \"Mini paper: longer questions (A level {course})\" sheets. Each print is a new paper.",
                  "check": "Mark it together one bullet a mark, then write the score and the topics to go back to on the tracker."},
        "use": [f"{key}-mixed"], "home": "Redo the questions that lost marks, then the online mixed exam questions.",
        "vocab": "exam conditions, mark scheme, topic, revise",
        "understand": "Your mini paper shows you lost marks on two topics. What do you do next?",
        "lookFor": "Goes back to those topics' lessons or exam sheets before the next mini paper, rather than just doing more papers.",
        "england": True, "alevel": ALEVEL[key]})

common = {"level": "Senior", "subject": "Maths", "strand": "Number", "codes": [], "england": True, "alevel": "A level Mathematics (Years 12 and 13)"}
lessons.append(dict(common, **{"id": "lesson-alevel-maths-what-the-exam-expects", "title": "A level maths climb: what the exam expects",
    "intention": "We are learning how A level Mathematics is examined and marked: the three papers, the large data set, method and accuracy marks, and conclusions in context.",
    "criteria": ["I know the papers, their times and their marks.", "I know what M, A and B marks are.", "I know statistics answers need a conclusion in context."],
    "steps": {"start": "Show an answer with a slip in the middle. Ask how many marks it should keep.",
              "teach": "Go through the \"What the exam expects: A level Mathematics\" sheet, then mark its model answers together. Find the student's exam board and download its large data set.",
              "practise": "Mark the model answers on the \"What the exam expects: A level Mathematics\" sheet together, then the online mixed exam questions with full working on paper.",
              "check": "Ask them to explain method marks, and what a statistics conclusion needs."},
    "use": ["y12-mixed", "y13-mixed"], "home": "Download your board's large data set and look at one column: what is it measuring?",
    "vocab": "paper, method mark, accuracy mark, large data set, in context, formulae booklet",
    "understand": "Why can a wrong final answer still earn most of a question's marks?",
    "lookFor": "Says method marks are for correct steps, and later steps done correctly with a wrong value still earn theirs."}))
lessons.append(dict(common, **{"id": "lesson-alevel-maths-exam-technique", "title": "A level maths climb: exam technique, command words and setting out",
    "intention": "We are learning what each A level command word asks for, and to set out working so every step can be given its mark.",
    "criteria": ["I know what show that, hence, exact, prove and interpret ask for.", "I set out working one step a line.", "I give answers to the accuracy asked for."],
    "steps": {"start": "Show 'Hence solve…' after a part (a). Ask what 'hence' tells them to do.",
              "teach": "Go through the command words on the \"A level exam technique: command words and setting out\" sheet. Show how a mark scheme gives a mark for each step.",
              "practise": "The \"A level exam technique: command words and setting out\" sheet: three questions set out step by step, then compared with the marking.",
              "check": "Ask them what 'show that' and 'give your answer in exact form' each need."},
    "use": ["y12-mixed", "y13-mixed"], "home": "Pick three online exam questions and write the working as bullets before checking.",
    "vocab": "command word, hence, show that, exact, prove, interpret",
    "understand": "Why does 'show that' need every step even though the answer is given?",
    "lookFor": "Says the marks are for the working: the answer is already in the question."}))
lessons.append(dict(common, **{"id": "lesson-alevel-maths-my-next-step", "title": "A level maths climb: my next step (working on your own, Years 12 and 13)",
    "intention": "We are learning to follow the climb on our own: take the check, practise the next topic, mark our own work and know when to move on.",
    "criteria": ["I can open the climb page and follow My next step.", "I read the marking after every question, even when I was right.", "I can mark my own working one bullet a step.", "I know when a topic is secure and when to move on."],
    "steps": {"start": "Ask: when you study on your own, how do you decide what to do next?",
              "teach": "Open popspell.com/climb.html?course=alevel together. Show My next step: it starts with the stage check, then picks the first topic that needs work, in the climb's order, and suggests a mini paper when a stage is nearly done. Explain that progress stays on this device only.",
              "practise": "The \"A level maths climb: my route through Years 12 and 13\" sheet: fill in the board, exam centre and target together, then do one practice set on the climb page.",
              "check": "Ask them to show you their next step on the climb page and explain why that topic comes next."},
    "use": ["y12-check", "y13-check"], "home": "Three or four sessions a week on the climb page, about an hour each, with a notebook for working.",
    "vocab": "self-guided, marking, secure, stage, next step",
    "understand": "Why read the marking even when you got the answer right?",
    "lookFor": "Says it shows which steps earn marks, so you can write them in the exam even when the last step goes wrong."}))

out = {"section": "England: A level maths exam climb (Years 12 and 13)", "lessons": lessons}
with open(HERE("content", "lessons", "21-alevel-maths.json"), "w") as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
